def has_triplet_sum(arr: list[int], x: int) -> bool:
    a = sorted(arr)
    n = len(a)
    for i in range(n - 2):
        l, r = i + 1, n - 1
        while l < r:
            s = a[i] + a[l] + a[r]
            if s == x:
                return True
            elif s < x:
                l += 1
            else:
                r -= 1
    return False
